{"explanation":"In vertex form y = a(x − h)² + k, the vertex sits at (h, k): h slides the parabola left/right (note the sign — x − h moves it right when h is positive), and k slides it up/down. The coefficient a controls the width — |a| > 1 narrows it, |a| < 1 widens it — and a negative a flips it upside down. Use the sliders to change each value, or drag the red vertex directly and watch h and k update, with the gray parent parabola y = x² shown for comparison.","manimCode":"let a = 1, h = 0, k = 0;

const AX_X = -0.8, AX_Y = -0.3;
const XU = 10 / 12;
const YU = 6.7 / 8;

const axes = new Axes({ xRange: [-6, 6, 1], yRange: [-4, 4, 1], xLength: 10, yLength: 6.7, tips: true });
axes.moveTo([AX_X, AX_Y, 0]);

function f(x) { return a * (x - h) * (x - h) + k; }

function xRangeForCurve() {
  if (Math.abs(a) < 0.05) return [-6, 6];
  const yBound = a > 0 ? 4.4 : -4.4;
  const span = Math.sqrt(Math.abs((yBound - k) / a));
  return [Math.max(-6, h - span), Math.min(6, h + span)];
}

const parent = axes.plot(x => x * x, { color: GRAY, xRange: [-2.1, 2.1], numSamples: 200 });
parent.setOpacity(0.35);

let curve = axes.plot(f, { color: YELLOW, xRange: xRangeForCurve(), numSamples: 300 });

const shiftSeg = new Polygon({ vertices: [[0, 0, 0], [0.001, 0, 0]], color: GREEN });
shiftSeg.setStrokeWidth(3).setFillOpacity(0);
shiftSeg.addUpdater(() => {
  const p0 = axes.c2p(0, 0);
  const p1 = axes.c2p(h, k);
  if (Math.abs(h) < 0.01 && Math.abs(k) < 0.01) {
    shiftSeg.setVertices([p0, [p0[0] + 0.001, p0[1], 0]]);
  } else {
    shiftSeg.setVertices([p0, p1]);
  }
});

const vertex = new Dot({ point: axes.c2p(0, 0), color: RED, radius: 0.1 });
vertex.addUpdater(() => vertex.moveTo(axes.c2p(h, k)));

const title = new MathTex({ latex: 'y = a(x-h)^2+k' });
await title.waitForRender();
title.moveTo([-3.3, 3.6, 0]);

function eqString() {
  const hs = h < 0 ? '+' : '-';
  const ks = k < 0 ? '-' : '+';
  return 'y = ' + a.toFixed(1) + '(x ' + hs + ' ' + Math.abs(h).toFixed(1) + ')\u00B2 ' + ks + ' ' + Math.abs(k).toFixed(1);
}

let eqLabel = new Text({ text: eqString(), color: YELLOW, fontSize: 26 });
let vLabel = new Text({ text: '(0.0, 0.0)', color: RED, fontSize: 20 });

function updateEqLabel() {
  scene.remove(eqLabel);
  eqLabel = new Text({ text: eqString(), color: YELLOW, fontSize: 26 });
  eqLabel.moveTo([-3.3, 3.05, 0]);
  scene.add(eqLabel);
}

function updateVLabel() {
  scene.remove(vLabel);
  vLabel = new Text({ text: '(' + h.toFixed(1) + ', ' + k.toFixed(1) + ')', color: RED, fontSize: 20 });
  const p = axes.c2p(h, k);
  let lx = p[0] + 1.1, ly = p[1] + 0.42;
  if (lx > 4.2) lx = p[0] - 1.1;
  if (ly > 3.2) ly = p[1] - 0.42;
  vLabel.moveTo([lx, ly, 0]);
  scene.add(vLabel);
}

function refresh() {
  scene.remove(curve);
  curve = axes.plot(f, { color: YELLOW, xRange: xRangeForCurve(), numSamples: 300 });
  scene.add(curve);
  updateEqLabel();
  updateVLabel();
}

const parentLabel = new Text({ text: 'parent: y = x\u00B2', color: GRAY, fontSize: 22 });
parentLabel.moveTo([1.9, 3.3, 0]);

await scene.play(new Create(axes));
await scene.play(new AnimationGroup([new Create(parent), new Create(curve)]));
await scene.play(new AnimationGroup([new FadeIn(vertex), new Write(title)]));
scene.add(shiftSeg, parentLabel);
updateEqLabel();
updateVLabel();

makeDraggable(vertex, scene, {
  constrainX: [-4.13, 2.53],
  constrainY: [-2.81, 2.21],
  onDrag: (mob, pos) => {
    h = Math.round(((pos[0] - AX_X) / XU) * 10) / 10;
    k = Math.round(((pos[1] - AX_Y) / YU) * 10) / 10;
    refresh();
  }
});

const controls = new Controls(scene, { position: 'top-right', width: 250 });
controls.addSlider({ label: 'a: stretch / flip', min: -3, max: 3, value: 1, step: 0.1, onChange: (v) => { a = v; refresh(); } });
controls.addSlider({ label: 'h: shift left/right', min: -4, max: 4, value: 0, step: 0.1, onChange: (v) => { h = v; refresh(); } });
controls.addSlider({ label: 'k: shift up/down', min: -3, max: 3, value: 0, step: 0.1, onChange: (v) => { k = v; refresh(); } });

await scene.wait(999999);"}

